    "readTime": "4 min read",
    "author": "Dr. Divya Sharma, MBBS (Gold Medalist), MD",
    "date": "Oct 26, 2025",
    "imageMode": "single",
    "singleImage": "https://www.drdivyasharma.com/assets/blog_inner/9daf6abf0e0d22e2b46948139dfd76f0.png",
